app.post("bookings") { req async throws -> Booking in
    let input = try req.content.decode(BookingInput.self)
    return try await req.db.transaction { database in
        guard let room = try await Room.find(input.roomID, on: database),
              room.isFree(input.stay) else {
            throw Abort(.conflict, reason: "room unavailable")
        }
        let booking = Booking(roomID: input.roomID, stay: input.stay)
        try await booking.save(on: database)
        return booking
    }
}
